import { describe, test, expect, vi, beforeEach, afterEach } from 'vitest';

vi.mock('@salesforce/pwa-kit-runtime/utils/ssr-config', () => ({
  getConfig: vi.fn(),
}));

import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
import { paymentMetadataHandler } from './paymentMetadata';
import { sendMagicLinkEmail } from './marketingCloud';
import type { SsrReq, SsrRes } from './types';

const PAYMENTS_URL = 'https://payments.example.demandware.net/metadata';
const PAYMENTS_HOST = new URL(PAYMENTS_URL).hostname;
const MARKETING_CLOUD_AUTH_HOST = 'auth.marketingcloudapis.com';
const MARKETING_CLOUD_REST_HOST = 'rest.marketingcloudapis.com';

/** Duration of the deliberate synchronous block used to occupy the event loop. */
const BLOCK_MS = 200;
/** Allowance for timer resolution when asserting on wall-clock durations. */
const TIMER_TOLERANCE_MS = 5;
/** Upper bound on how long to wait for Node to report an unhandled rejection. */
const REJECTION_SETTLE_TIMEOUT_MS = 1_000;

type MockRes = SsrRes & { statusCode?: number; body?: unknown };

function createMockRes(): MockRes {
  // Built incrementally: every member of SsrRes is assigned immediately below,
  // so the object is complete before it is returned.
  const res = {} as MockRes;
  res.status = vi.fn().mockImplementation((code: number) => {
    res.statusCode = code;
    return res;
  });
  res.json = vi.fn().mockImplementation((data: unknown) => {
    res.body = data;
    return res;
  });
  res.send = vi.fn().mockImplementation((data: unknown) => {
    res.body = data;
    return res;
  });
  res.setHeader = vi.fn().mockReturnValue(res);
  res.set = vi.fn().mockReturnValue(res);
  return res;
}

function createMockReq(): SsrReq {
  return {
    protocol: 'https',
    body: { email_id: 'shopper@example.com', token: 'reset-token' },
    get: vi.fn().mockReturnValue('zimmermann.com'),
    params: {},
    query: {},
    headers: {},
  };
}

/**
 * As-is baseline evidence for SFCC-681 (TSD-SFCC-681, "MRT Application Topology").
 *
 * The first two tests exercise the real SSR handler functions rather than stand-ins, so the
 * TSD's Problem Statement rests on reproducible evidence rather than assertion. The third
 * needs no handler: it demonstrates a property of Node's event loop itself.
 *
 * These document CURRENT behaviour. The first two are expected to change once the safeguards
 * in the TSD's §5 are implemented, and should then be updated to assert the fixed behaviour
 * rather than deleted. The third documents a permanent property of any single-process model
 * and is expected to keep passing unchanged.
 *
 * Every fetch is mocked; nothing here contacts a real network endpoint.
 */
describe('SSR shared-process blast radius (SFCC-681 as-is baseline)', () => {
  beforeEach(() => {
    vi.stubEnv('MARKETING_CLOUD_CLIENT_ID', 'test-client-id');
    vi.stubEnv('MARKETING_CLOUD_CLIENT_SECRET', 'test-client-secret');
    vi.stubEnv('MARKETING_CLOUD_SUBDOMAIN', 'test-subdomain');

    // getConfig returns the full PWA Kit runtime config; only the fields these two
    // handlers actually read are stubbed here.
    vi.mocked(getConfig).mockReturnValue({
      app: {
        sfPayments: { metadataUrl: PAYMENTS_URL },
        login: { resetPassword: { landingPath: '/reset-password' }, passwordless: {} },
      },
    } as ReturnType<typeof getConfig>);

    vi.stubGlobal(
      'fetch',
      vi.fn((input: string | URL) => {
        const href = String(input);
        // Every upstream fails identically (503), so the modules face the same condition and
        // the only variable is how each one handles it. Each branch stubs only the Response
        // members the handlers touch: ok, status, json.
        if (href.includes(PAYMENTS_HOST)) {
          return Promise.resolve({ ok: false, status: 503 } as Response);
        }
        // Note: marketingCloud.ts caches its access token at module scope, so this auth
        // branch is only reached by whichever test runs first. Later tests reuse the cached
        // token and go straight to the send branch below. That does not affect what these
        // tests assert, but any future assertion on token-exchange behaviour would be
        // order-dependent and should reset module state first.
        if (href.includes(MARKETING_CLOUD_AUTH_HOST)) {
          return Promise.resolve({ ok: true, json: () => Promise.resolve({ access_token: 'fake-token' }) } as Response);
        }
        if (href.includes(MARKETING_CLOUD_REST_HOST)) {
          // Marketing Cloud's send-email endpoint is down.
          return Promise.resolve({ ok: false, status: 503 } as Response);
        }
        return Promise.reject(new Error(`Unexpected fetch in test: ${href}`));
      }),
    );
  });

  afterEach(() => {
    vi.unstubAllGlobals();
    vi.unstubAllEnvs();
    vi.clearAllMocks();
  });

  test('one integration rejects uncaught while a sibling catches its own failure and responds', async () => {
    const paymentsRes = createMockRes();
    const magicLinkRes = createMockRes();

    // Both modules face the same upstream failure (503) at the same time, so handling is the
    // only variable. allSettled reports each outcome independently of the other.
    const [paymentsOutcome, magicLinkOutcome] = await Promise.allSettled([
      paymentMetadataHandler({}, paymentsRes),
      sendMagicLinkEmail(createMockReq(), magicLinkRes, '/reset-password', 'reset-template'),
    ]);

    // paymentMetadataHandler catches at its own boundary and converts the failure into an
    // HTTP response, so its promise still fulfils and the caller is told what happened.
    expect(paymentsOutcome.status).toBe('fulfilled');
    expect(paymentsRes.statusCode).toBe(500);
    expect(paymentsRes.body).toEqual(expect.objectContaining({ error: 'Failed to fetch metadata' }));

    // sendMagicLinkEmail has no try/catch around its Marketing Cloud call, so the identical
    // failure escapes the module instead. That asymmetry is the finding.
    expect(magicLinkOutcome.status).toBe('rejected');
  });

  test('the shipped route shape leaves the request unanswered when its integration fails', async () => {
    const magicLinkRes = createMockRes();

    // The real ssr.js route handlers never await or catch this call, so the only thing
    // between the rejection and an undetected failure is pwa-kit-runtime's own global
    // handler (build-remote-server.js registers process.on('unhandledRejection',
    // catchAndLog), which logs and nothing more). Registering an equivalent listener here
    // reproduces that real safety net, lets the test assert the rejection genuinely goes
    // unhandled by application code, and stops Vitest reporting it as a stray
    // run-failing error.
    let capturedRejection: unknown;
    const onUnhandledRejection = (reason: unknown) => {
      capturedRejection = reason;
    };
    process.once('unhandledRejection', onUnhandledRejection);

    try {
      // Reproduces the floating-promise shape of the shipped call sites in ssr.js, where
      // sendMagicLinkEmail is invoked inside a .then() callback without being returned,
      // awaited or chained.
      //
      // One link is deliberately elided: the real chain begins with
      // validateSlasCallbackToken(token).then(...), and that function throws on an invalid
      // or expired token. So the shipped code has a SECOND unobserved rejection source that
      // this test does not cover, and which a fix targeting only sendMagicLinkEmail would
      // not close. See TSD §5.2.
      //
      // `void` marks the promises as deliberately unobserved for the linter only; it
      // attaches no handler and leaves the behaviour under test unchanged.
      void Promise.resolve().then(() => {
        void sendMagicLinkEmail(createMockReq(), magicLinkRes, '/reset-password', 'reset-template');
      });

      // Node reports unhandled rejections on a macrotask boundary, so poll rather than
      // sleeping for a fixed duration.
      await vi.waitFor(
        () => {
          expect(capturedRejection).toBeInstanceOf(Error);
        },
        { timeout: REJECTION_SETTLE_TIMEOUT_MS, interval: 10 },
      );
      expect((capturedRejection as Error).message).toMatch(/Marketing Cloud/i);

      // The other half of the finding: the shopper is told nothing at all. The framework's
      // handler only logs, and nothing in that path touches this response. The request is
      // left to run out MRT's execution ceiling and return a generic 502.
      // eslint-disable-next-line @typescript-eslint/unbound-method -- plain vi.fn() mocks with no `this` dependency; standard Vitest call-count assertion.
      expect(magicLinkRes.send).not.toHaveBeenCalled();
      // eslint-disable-next-line @typescript-eslint/unbound-method -- see above
      expect(magicLinkRes.json).not.toHaveBeenCalled();
      // eslint-disable-next-line @typescript-eslint/unbound-method -- see above
      expect(magicLinkRes.status).not.toHaveBeenCalled();
    } finally {
      process.removeListener('unhandledRejection', onUnhandledRejection);
    }
  });

  test('a synchronous CPU-bound operation blocks unrelated concurrent work', async () => {
    // Nothing is mocked here. This is a property of Node's single-threaded event loop
    // rather than of any integration's code, and it is not addressable by connection
    // pools, which govern sockets rather than who holds the JS thread. It therefore
    // documents a permanent trade-off of the single-application model rather than a
    // defect to be fixed.
    let fastResolvedAt = 0;
    const start = Date.now();

    const fastRequest = Promise.resolve().then(() => {
      fastResolvedAt = Date.now();
    });

    const blockUntil = Date.now() + BLOCK_MS;
    while (Date.now() < blockUntil) {
      // Busy-wait, standing in for a heavy synchronous operation such as a large
      // JSON.parse or an expensive regex inside an integration handler.
    }

    await fastRequest;
    const fastRequestDelay = fastResolvedAt - start;

    // The fast work should resolve almost immediately. Instead it waits out the entire
    // blocking operation, because both share one event loop. The upper bound guards
    // against the assertion passing for an unrelated reason.
    expect(fastRequestDelay).toBeGreaterThanOrEqual(BLOCK_MS - TIMER_TOLERANCE_MS);
    expect(fastRequestDelay).toBeLessThan(BLOCK_MS * 2);
  });
});

/**
 * How long does global fetch wait on an upstream that accepts the TCP
 * connection but never sends a response?
 *
 * The threshold that matters is MRT's own execution ceiling: 20s production /
 * 16s non-production. If undici's default exceeds that, MRT kills the request
 * before undici does, and the shopper gets a generic 502 rather than the
 * integration failing cleanly.
 */
import http from 'node:http';

const MRT_PROD_CEILING_MS = 20_000;

// Accepts the connection, then holds it open forever without responding.
const blackHole = http.createServer(() => {
  /* deliberately never respond */
});

const port = await new Promise((resolve) =>
  blackHole.listen(0, '127.0.0.1', () => resolve(blackHole.address().port)),
);

console.log('node', process.version);
console.log(`probing default response timeout, capped at MRT's ${MRT_PROD_CEILING_MS / 1000}s production ceiling...\n`);

const start = Date.now();
const result = await Promise.race([
  fetch(`http://127.0.0.1:${port}/`)
    .then(() => ({ kind: 'responded' }))
    .catch((err) => ({ kind: 'rejected', message: err.message, cause: err.cause?.message })),
  new Promise((resolve) => setTimeout(() => resolve({ kind: 'still-waiting' }), MRT_PROD_CEILING_MS)),
]);
const elapsed = Date.now() - start;

if (result.kind === 'still-waiting') {
  console.log(`RESULT: fetch was STILL WAITING after ${elapsed}ms.`);
  console.log(`         undici's default timeout exceeds MRT's ${MRT_PROD_CEILING_MS / 1000}s production ceiling.`);
  console.log('         => MRT terminates the request first; the shopper gets a generic 502.');
  console.log('         => An explicit per-origin bodyTimeout is what makes the integration fail cleanly instead.');
} else if (result.kind === 'rejected') {
  console.log(`RESULT: fetch rejected after ${elapsed}ms -> ${result.message}${result.cause ? ` (${result.cause})` : ''}`);
  console.log(`         default timeout is BELOW MRT's ceiling, so undici fails first.`);
} else {
  console.log(`RESULT: unexpectedly got a response after ${elapsed}ms.`);
}

blackHole.close();
process.exit(0);

/**
 * Empirical check: does Node's built-in undici (backing global fetch) isolate
 * connections per origin by default, and are per-origin connections bounded?
 *
 * Uses ONLY global fetch and node:http, so it measures the exact runtime our
 * SSR code uses. No undici import: the npm `undici` package keeps its own
 * global dispatcher, separate from Node's internal one, so importing it would
 * inspect the wrong thing.
 */
import http from 'node:http';

const listen = (server) =>
  new Promise((resolve) => server.listen(0, '127.0.0.1', () => resolve(server.address().port)));

const SLOW_MS = 1500;

// Track how many sockets each server sees concurrently: this reveals whether
// undici bounds connections per origin.
let slowConcurrent = 0;
let slowPeakConcurrent = 0;

const slowServer = http.createServer((req, res) => {
  slowConcurrent += 1;
  slowPeakConcurrent = Math.max(slowPeakConcurrent, slowConcurrent);
  setTimeout(() => {
    slowConcurrent -= 1;
    res.writeHead(200).end('slow');
  }, SLOW_MS);
});

const fastServer = http.createServer((req, res) => {
  res.writeHead(200).end('fast');
});

const slowPort = await listen(slowServer);
const fastPort = await listen(fastServer);
const SLOW = `http://127.0.0.1:${slowPort}/`;
const FAST = `http://127.0.0.1:${fastPort}/`;

console.log('node', process.version);

// --- 1. Baseline: fast origin, no competing load -------------------------
{
  const t = Date.now();
  await fetch(FAST).then((r) => r.text());
  console.log('\nbaseline  | fast origin, no load   :', Date.now() - t, 'ms');
}

// --- 2. Saturate the SLOW origin, then hit the FAST origin ---------------
const FLOOD = 100;
const floodStart = Date.now();
const flood = Array.from({ length: FLOOD }, () => fetch(SLOW).then((r) => r.text()));

// Let the flood get genuinely in flight before measuring.
await new Promise((r) => setTimeout(r, 300));

const tFast = Date.now();
await fetch(FAST).then((r) => r.text());
const fastUnderLoad = Date.now() - tFast;
console.log(`under load| fast origin (${FLOOD} slow in flight):`, fastUnderLoad, 'ms');

// --- 3. Same-origin contention -------------------------------------------
const tSlow = Date.now();
await fetch(SLOW).then((r) => r.text());
const slowUnderLoad = Date.now() - tSlow;
console.log('under load| slow origin (same origin) :', slowUnderLoad, `ms (server delay ${SLOW_MS}ms)`);

await Promise.all(flood);
console.log('          | all', FLOOD, 'slow requests done in', Date.now() - floodStart, 'ms');
console.log('          | peak concurrent sockets at slow origin:', slowPeakConcurrent);

// --- 4. Verdict -----------------------------------------------------------
console.log('\n--- VERDICT ---');
console.log(
  fastUnderLoad < 300
    ? `[A] CROSS-ORIGIN ISOLATED by default. Unrelated origin served in ${fastUnderLoad}ms while ${FLOOD} requests were stalled on another origin.`
    : `[A] CROSS-ORIGIN STARVATION. Unrelated origin delayed to ${fastUnderLoad}ms.`,
);
console.log(
  slowPeakConcurrent >= FLOOD
    ? `[B] PER-ORIGIN CONNECTIONS UNBOUNDED: ${slowPeakConcurrent} concurrent sockets opened to one origin (no default cap).`
    : `[B] PER-ORIGIN CAP IN EFFECT: peaked at ${slowPeakConcurrent} concurrent sockets, so undici bounds connections per origin.`,
);

slowServer.close();
fastServer.close();

